function parseListItems(text: string): string[] {
  if (!text) return [];
  const raw = text.replace(/\n+/g, ',').replace(/\s+and\s+/gi, ',').replace(/\s*&\s*/g, ',');
  const parts = raw.split(',').map(s => s.trim()).filter(Boolean);
