// ─── Sprite Library ────────────────────────────────────────────────
const SpriteLibrary: React.FC = () => {
  const [sprites, setSprites] = useState<Sprite[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;

    async function load() {
      try {
        const res = await fetch("/api/summon-ai-sprite/list?includeGif=1&limit=50");
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        if (!cancelled) {
          setSprites(data.sprites ?? []);
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : "Failed to load sprites");
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    }

    load();
    return () => {
      cancelled = true;
    };
  }, []);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-6 text-xs text-[#d4c0e8]/50">
        Loading sprites…
      </div>
    );
  }

  if (error) {
    return (
      <div className="text-center py-6 text-xs text-red-400/70">{error}</div>
    );
  }

  if (sprites.length === 0) {
    return (
      <div className="text-center py-6 space-y-2">
        <div className="text-2xl opacity-40">👾</div>
        <div className="text-xs text-[#d4c0e8]/50">
          No sprites yet. Ask Pearl to summon one!
        </div>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 gap-3 max-h-72 overflow-y-auto">
      {sprites.map((sprite) => (
        <div
          key={sprite._id}
          className="group relative flex flex-col items-center rounded-xl border border-white/5 bg-white/[0.02]
            hover:border-[#D94F8E]/30 hover:bg-white/[0.05] transition-all cursor-pointer p-2"
          title={sprite.description || sprite.name}
        >
          <div className="w-14 h-14 rounded-lg bg-white/[0.04] flex items-center justify-center overflow-hidden mb-1.5">
            {sprite.gifData ? (
              <img
                src={`data:${sprite.gifMimeType || "image/gif"};base64,${sprite.gifData}`}
                alt={sprite.name}
                className="w-full h-full object-contain"
              />
            ) : (
              <span className="text-2xl opacity-40">👾</span>
            )}
          </div>
          <span className="text-[10px] text-[#d4c0e8]/70 text-center truncate w-full">
            {sprite.name}
          </span>
        </div>
      ))}
    </div>
  );
};

// ─── Main Launchpad ────────────────────────────────────────────────
const CreationLaunchpad: React.FC = () => {
  return (
    <div
      className="flex flex-col h-full overflow-y-auto"
      style={{
        backgroundColor: "#0a0614",
        color: "#faf8f5",
        fontFamily: "Gohufont, monospace",
      }}
    >
      {/* Header */}
      <div className="flex items-center gap-3 px-5 py-4 border-b border-white/10 shrink-0">
        <span className="text-2xl">🚀</span>
        <div>
          <div className="text-base font-bold tracking-wide">Creation Launchpad</div>
          <div className="text-[11px] text-[#d4c0e8]/50">
            Build games, manage pipelines, browse sprites
          </div>
        </div>
      </div>

      {/* Sections */}
      <div className="flex-1 p-4 space-y-2">
        <Section title="Game Creator" icon="🎮">
          <GameCreator />
        </Section>

        <Section title="Pipeline Output" icon="🔧" defaultOpen={false}>
          <PipelineOutput />
        </Section>

        <Section title="Sprite Library" icon="👾">
          <SpriteLibrary />
        </Section>
      </div>
    </div>
  );
};

export default CreationLaunchpad;

